window.ENEM_RESOLUTION_CHUNKS=window.ENEM_RESOLUTION_CHUNKS||{};window.ENEM_RESOLUTION_CHUNKS["data/resolucoes/linguagens_2023.js"]=[{"title":"Desperdício alimentar e ambiente","steps":["A comida descartada forma o cenário do cartaz.","O texto associa toneladas de resíduos aos aterros e recomenda aproveitar sobras e refrigerar perecíveis.","B sintetiza a advertência ambiental, não uma defesa de ampliar lixões."],"alternatives":{"A":"O cartaz recomenda reduzir o descarte, não aumentar os lixões.","B":"A relação entre alimento jogado fora e aterros evidencia o dano ambiental.","C":"Não se anuncia doação de alimentos por estabelecimentos comerciais.","D":"Food for thought é um jogo de palavras, não um diagnóstico de desnutrição.","E":"Recomendar refrigeração não implica afirmar que faltam geladeiras nas casas."},"takeaway":"Interprete o jogo verbal junto da imagem e das recomendações práticas do cartaz.","key":"linguagens:L497","area":"linguagens","year":2023,"number":1,"answer":"B","subject":"Inglês","topic":"Interpretação de textos em língua inglesa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[2,4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A metáfora de uma humanidade conectada","steps":["A negação da ilha recusa a ideia de indivíduo isolado e autossuficiente.","Cada pessoa é parte do continente, e a morte de qualquer outra diminui o eu lírico.","B nomeia essa conexão; empatia é uma implicação possível, não a relação metafórica mais direta."],"alternatives":{"A":"A morte aparece como perda compartilhada, não principalmente como medo individual.","B":"Ilha negada e continente afirmado expressam interdependência entre as pessoas.","C":"A expressão nega o isolamento em vez de reforçar a solidão.","D":"Não se descreve risco de devastação física de ilhas ou continentes.","E":"Empatia é compatível com o poema, mas a expressão destaca diretamente a conexão."},"takeaway":"Numa metáfora, procure a relação estrutural construída, antes de inferir uma recomendação moral.","key":"linguagens:L498","area":"linguagens","year":2023,"number":2,"answer":"B","subject":"Inglês","topic":"Interpretação de textos em língua inglesa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[2,4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A bagagem plural dos refugiados","steps":["A repetição de we carry reúne perdas, línguas, profissões, memórias e projetos.","As referências a guerras e mudanças ambientais mostram trajetórias distintas, não uma única causa.","A viagem dá forma a essa pluralidade de experiências, D."],"alternatives":{"A":"Choques culturais são possíveis, mas não resumem o inventário de vivências.","B":"O poema não avalia impactos do ensino escolar de história.","C":"A crise ambiental aparece entre várias experiências, não como única luta.","D":"Memórias, habilidades, perdas e expectativas compõem a diversidade da bagagem humana.","E":"Diplomas já são carregados; o poema não propõe capacitação como solução central."},"takeaway":"Repetições podem agregar diferenças sob uma experiência comum sem apagar a pluralidade.","key":"linguagens:L499","area":"linguagens","year":2023,"number":3,"answer":"D","subject":"Inglês","topic":"Interpretação de textos em língua inglesa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[2,5],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A mistura realiza a tese do poema","steps":["O poema alterna expressões inglesas e espanholas no próprio enunciado.","Referências musicais, tecnológicas e culturais reforçam a aproximação.","A forma exemplifica convergência linguístico-cultural, A; não é falta de domínio de uma língua."],"alternatives":{"A":"As duas línguas e suas referências culturais se encontram na construção do Spanglish.","B":"A alternativa é ampla e não nomeia a integração que a forma concretiza.","C":"O texto não pretende identificar uma tendência literária específica.","D":"O tom valoriza a mistura; não se organiza como denúncia central de discriminação.","E":"A presença de gêneros musicais não sugere proibição ou censura."},"takeaway":"Além do que um poema afirma, observe como a escolha das palavras realiza seu tema.","key":"linguagens:L500","area":"linguagens","year":2023,"number":4,"answer":"A","subject":"Inglês","topic":"Interpretação de textos em língua inglesa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[3,5],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A imagem desmente a promessa de diversidade","steps":["A fala garante igualdade independentemente de idade, raça ou gênero.","O escritório mostra funcionários visualmente muito semelhantes entre si.","A contradição irônica destaca falta de diversidade, B, em vez de elogiar a organização."],"alternatives":{"A":"As roupas são parte do cenário, mas o contraste principal envolve diversidade humana.","B":"A homogeneidade visual põe em dúvida a declaração inclusiva feita na legenda.","C":"Há interação entre personagens, mas a finalidade é crítica, não descritiva.","D":"A ironia impede ler a fala como elogio literal à organização.","E":"A cena não mostra cooperação como objetivo central da crítica."},"takeaway":"No cartum, compare a promessa verbal com o que a cena efetivamente exibe.","key":"linguagens:L501","area":"linguagens","year":2023,"number":5,"answer":"B","subject":"Inglês","topic":"Interpretação de textos em língua inglesa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[3,5],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Juntos acrescenta cooperação ao desempenho","steps":["O lema já valoriza rapidez, altura e força.","A inclusão de juntos explicita solidariedade entre participantes.","A alteração associa o lema à cooperatividade, D, sem eliminar a busca de excelência."],"alternatives":{"A":"Não se juntam dois lemas independentes: acrescenta-se um valor ao anterior.","B":"A relação administrativa com o COI não é o sentido da palavra adicionada.","C":"A expressão é genérica; a novidade específica é o valor cooperativo.","D":"Juntos destaca solidariedade e realização compartilhada no esporte.","E":"Eventos atléticos já eram o contexto do lema antes da mudança."},"takeaway":"Em perguntas sobre alteração textual, isole o efeito do elemento novo.","key":"linguagens:L658","area":"linguagens","year":2023,"number":6,"answer":"D","subject":"Educação Física","topic":"Esporte, inclusão e práticas corporais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[6],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O corpo inscreve raça, gênero e resistência","steps":["A narradora enumera partes do corpo e emprega imagens de força e agressividade.","A referência à escravidão liga a experiência corporal à violência histórica.","A articulação revela marcas raciais e de gênero na identidade, A."],"alternatives":{"A":"Corpo feminino, violência e memória da escravidão se combinam na construção identitária.","B":"A narradora menciona a abolição no Ceará sem ter como objetivo principal negar seu pioneirismo.","C":"O corpo é apresentado de modo perturbador, não como reprodução de um padrão de beleza.","D":"As imagens intensas não constituem sobretudo um desejo de espiritualidade.","E":"A paisagem não é o objeto central: a narração se organiza pela identidade corporal."},"takeaway":"Observe como o corpo literário pode carregar memória social e também potência de resistência.","key":"linguagens:L368","area":"linguagens","year":2023,"number":7,"answer":"A","subject":"Literatura","topic":"Literatura contemporânea (pós-1960)","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[6],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O preconceito inventa uma língua ideal","steps":["O português brasileiro é tratado como se não fosse português legítimo.","Essa desqualificação pressupõe uma variedade portuguesa ideal e superior.","C descreve a crença preconceituosa; a resolução não endossa que essa superioridade exista."],"alternatives":{"A":"A dificuldade de publicação literária não é a explicação apresentada.","B":"Não se demonstram diferenças de escolaridade que justifiquem a hostilidade.","C":"Alguns falantes idealizam sua própria variedade e inferiorizam a brasileira.","D":"O intercâmbio cultural não gera necessariamente desqualificação de variedades.","E":"Distância territorial produz diferenças, mas não explica por si o juízo de superioridade."},"takeaway":"Diferença linguística é um fato; transformar diferença em hierarquia é uma avaliação social.","key":"linguagens:L222","area":"linguagens","year":2023,"number":8,"answer":"C","subject":"Variação linguística","topic":"Oralidade, registros e adequação comunicativa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[6],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Uma rede diversa faz circular notícias","steps":["O trecho enumera ordens mendicantes, jograis, viajantes e correios.","Esses agentes e meios formam uma rede de circulação na sociedade medieval.","E explica a eficácia pelo conjunto disponível, e não somente pela velocidade de um cavalo."],"alternatives":{"A":"A velocidade é mencionada, mas não abrange a diversidade dos canais de circulação.","B":"Não se atribui a eficácia a alto letramento da população marginalizada.","C":"Selos procuram autenticar mensagens; não são descritos como censura pública.","D":"A nobreza não aparece como única fonte de legitimidade das notícias.","E":"Agentes móveis e correios oferecem diferentes vias para transmitir informação."},"takeaway":"Uma enumeração de meios frequentemente fundamenta uma explicação sistêmica, não uma causa isolada.","key":"linguagens:L794","area":"linguagens","year":2023,"number":9,"answer":"E","subject":"Tecnologias da Informação e Comunicação","topic":"Leitura crítica da mídia e circulação da informação","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[7],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Pistas linguísticas ajudam a identificar perfis falsos","steps":["A reportagem apresenta horários de publicação e repetição vocabular como pistas.","A baixa variedade das mensagens pode resultar da administração simultânea de muitos perfis.","E expressa sua utilidade investigativa: identificar padrões de difusão de informações inverídicas."],"alternatives":{"A":"A análise não tem como finalidade fiscalizar toda a profissão de TI.","B":"O texto investiga a atuação de perfis, não ensina a desenvolver trolls.","C":"Os horários são pistas, não uma proposta de flexibilização de jornadas.","D":"Regulamentação pode ser debatida, mas não é a função imediata da análise descrita.","E":"Repetição e outros comportamentos ajudam a reconhecer operações de desinformação."},"takeaway":"Uma pista de padrão não é prova isolada: a reportagem combina linguagem e comportamento.","key":"linguagens:L727","area":"linguagens","year":2023,"number":10,"answer":"E","subject":"Tecnologias da Informação e Comunicação","topic":"Cultura digital, redes e gêneros digitais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[7],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Os dados servem à sensibilização","steps":["O texto enumera riscos e apresenta projeção alarmante para o trânsito.","Depois recomenda valores e atitudes responsáveis para preservar vidas.","O objetivo global é sensibilizar o público, D; causas e números são meios argumentativos."],"alternatives":{"A":"Enumerar causas é uma etapa do argumento, não sua finalidade completa.","B":"Contextualizar o Maio Amarelo não esgota o apelo à mudança de conduta.","C":"O número alarmante sustenta a argumentação, não é o objetivo final isolado.","D":"A defesa de menos pressa e mais respeito busca estimular direção responsável.","E":"O texto inclui impunidade e civilidade, não restringe tudo a emoções."},"takeaway":"Distinga o recurso usado para argumentar da ação que o texto pretende provocar no leitor.","key":"linguagens:L091","area":"linguagens","year":2023,"number":11,"answer":"D","subject":"Interpretação de texto e gêneros textuais","topic":"Argumentação e pontos de vista","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[7],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Uma descrição feita de impressões sensoriais","steps":["A narradora observa roupa apertada, movimentos lentos, perfume e maquiagem.","O detalhe corporal compõe a impressão de uma figura extravagante ligada às vestimentas maternas.","C identifica essa descrição impressionista do fetiche do personagem, não uma explicação sociológica dos patrões."],"alternatives":{"A":"O efeito decorre sobretudo das imagens sensoriais, não de palavras ambíguas.","B":"O trecho não se organiza como denúncia das relações de trabalho doméstico.","C":"Sensações visuais, olfativas e corporais constroem a singularidade da apresentação do personagem.","D":"A observadora é identificável; não se destaca um foco narrativo indefinido.","E":"Há estranheza, mas não uma investigação de mistério entre parentes."},"takeaway":"Descrever por impressões é compor uma percepção do personagem, não emitir um diagnóstico clínico.","key":"linguagens:L431","area":"linguagens","year":2023,"number":12,"answer":"C","subject":"Literatura","topic":"Modernismo: romance de 1930 e prosa da segunda geração","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[8],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A memória desemboca num repouso afetivo","steps":["O toque percorre marcas do tempo e evoca amores anteriores.","O último amor é o interlocutor presente, seguido de finalmente repousar dos cuidados.","C sintetiza serenidade e entrega; as lembranças não configuram vontade de abandonar o presente."],"alternatives":{"A":"As marcas são acolhidas pelo toque, não expostas como vergonha dominante.","B":"O verso final resolve a trajetória em repouso, não indecisão atual.","C":"A relação presente aparece como acolhimento e pacificação dos cuidados.","D":"O poema chega ao presente amoroso, sem pedir retorno aos relacionamentos anteriores.","E":"A enumeração de amores desemboca em repouso, não busca de prazer passageiro."},"takeaway":"O desfecho de um poema pode orientar o sentido afetivo de todas as lembranças anteriores.","key":"linguagens:L415","area":"linguagens","year":2023,"number":13,"answer":"C","subject":"Literatura","topic":"Modernismo: primeira geração","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[8],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O prazer está no modo de contar","steps":["Os moradores já tinham ouvido o capítulo no rádio, mas querem ouvi-lo novamente.","Soropita demora, interpreta e prende a atenção, recriando oralmente o enredo.","D explica a preferência pelo jeito singular de narrar, não por informação inédita."],"alternatives":{"A":"O atrativo é a voz do recontador, não a qualidade técnica do aparelho.","B":"A estabilidade do enredo não explica o prazer específico na nova narração.","C":"O texto afirma que os ouvintes já conheciam o capítulo.","D":"A performance de Soropita dá nova força à história conhecida.","E":"O desejo de repetir não é apresentado como dificuldade de entender o enredo."},"takeaway":"Narrar não é apenas transmitir informações: ritmo e performance também produzem experiência estética.","key":"linguagens:L783","area":"linguagens","year":2023,"number":14,"answer":"D","subject":"Tecnologias da Informação e Comunicação","topic":"Tecnologias, comunicação e transformações sociais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Registros únicos sustentam memória e identidade","steps":["Gravações preservavam línguas, cantos e rituais, inclusive de falantes já falecidos.","A impossibilidade de refazer certas gravações torna parte da perda irreparável.","B dimensiona o dano à memória e identidade nacionais sem afirmar que toda cultura indígena desapareceu."],"alternatives":{"A":"Retomar pesquisas é uma consequência, mas não expressa a irreversibilidade principal.","B":"Registros sem possibilidade de reprodução constituem perdas de memória e identidade.","C":"Pesquisas continuam possíveis; nem todo trabalho na área depende do acervo destruído.","D":"O incêndio não extingue automaticamente culturas vivas de povos originários.","E":"O próprio texto prevê novas viagens entre os Tikuna, não impossibilidade total de estudo."},"takeaway":"Evite alternativas absolutas que ampliem uma perda grave para o desaparecimento de toda uma cultura.","key":"linguagens:L728","area":"linguagens","year":2023,"number":15,"answer":"B","subject":"Tecnologias da Informação e Comunicação","topic":"Cultura digital, redes e gêneros digitais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Libras também apresenta variação","steps":["O texto aproxima nomes regionais em português de sinais diferentes em Libras.","As diferenças dependem de região, geração e outros fatores sociais.","A reconhece variação como propriedade de línguas naturais, sem supor línguas regionais totalmente distintas."],"alternatives":{"A":"A Libras apresenta variação social, regional e histórica como outras línguas.","B":"Os exemplos mostram sinais diferentes para o mesmo referente, não necessariamente novos sentidos.","C":"Diferença em alguns sinais não implica transformação de toda a estrutura linguística.","D":"Variedades regionais não são automaticamente línguas independentes.","E":"O texto não afirma que as diferenças inviabilizem a compreensão entre usuários."},"takeaway":"Uma língua não precisa ser uniforme para ser uma língua legítima e compartilhada.","key":"linguagens:L189","area":"linguagens","year":2023,"number":16,"answer":"A","subject":"Variação linguística","topic":"Variedades linguísticas, identidade e preconceito","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[10],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Colchetes abertos como identidade editorial","steps":["O editor explica que os sinais voltados para fora sugerem receptividade.","A publicação se propõe a receber e fazer circular ideias originadas nos livros.","D relaciona forma gráfica e identidade, não rigor da pontuação convencional."],"alternatives":{"A":"Não se limita a revista a especialistas em leitura acadêmica.","B":"O uso deliberadamente não convencional não demonstra rigor normativo.","C":"A enumeração de temas não estabelece exclusividade de uma área.","D":"A abertura visual dos sinais simboliza acolhimento e circulação de ideias.","E":"O efeito não se restringe ao design dos artigos, mas à identidade da revista."},"takeaway":"Sinais de pontuação também podem adquirir funções simbólicas no projeto visual.","key":"linguagens:L190","area":"linguagens","year":2023,"number":17,"answer":"D","subject":"Variação linguística","topic":"Variedades linguísticas, identidade e preconceito","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[10],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Do impresso às telas: informação em excesso","steps":["A primeira letra apresenta notícias, fotos e nomes nas bancas.","A segunda associa telas e algoritmos a um ritmo crescente de estímulos.","B identifica a percepção comum da profusão informacional em tecnologias de épocas distintas."],"alternatives":{"A":"As cores aparecem em ambas, mas não são por si o eixo comum mais abrangente.","B":"Bancas e plataformas digitais compõem contextos diferentes de abundância informacional.","C":"A oposição explícita vício/virtude não organiza igualmente o primeiro fragmento.","D":"A liberdade de expressão não é a busca central comum aos trechos.","E":"A comercialização não recebe a mesma crítica explícita nas duas letras."},"takeaway":"Compare os textos pelo denominador comum efetivo, não por uma palavra presente em ambos.","key":"linguagens:L795","area":"linguagens","year":2023,"number":18,"answer":"B","subject":"Tecnologias da Informação e Comunicação","topic":"Leitura crítica da mídia e circulação da informação","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[10],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Poesia e estatística sustentam a denúncia","steps":["Os versos expõem a naturalização da morte de pessoas negras.","Os números mostram sua participação desproporcional entre vítimas de homicídio.","D sintetiza a convergência dos recursos na denúncia de vulnerabilidade à violência."],"alternatives":{"A":"A relevância da poesia é parcial; não há série temporal provando crescimento diário.","B":"Não se mede a expansão da temática do preconceito na literatura.","C":"Os dados são de violência, não uma contagem de expressões artísticas.","D":"Citação e estatísticas convergem para evidenciar a exposição da população negra à violência.","E":"O texto não quantifica aumento de participação juvenil em movimentos culturais."},"takeaway":"Confira o que os números realmente medem antes de transferi-los a outra conclusão.","key":"linguagens:L092","area":"linguagens","year":2023,"number":19,"answer":"D","subject":"Interpretação de texto e gêneros textuais","topic":"Argumentação e pontos de vista","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[11],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Linguagem especializada pode excluir","steps":["A autora pergunta quem compreende os discursos de profissionais que decidem destinos.","Em seguida denuncia o impedimento de compreensão e a manutenção de privilégios.","E nomeia a crítica ao uso especializado como barreira de poder, não uma condenação a toda especialização."],"alternatives":{"A":"A abertura religiosa introduz o tema, mas não prova a exclusão pelo poder.","B":"O receio sobre o futuro não é a estratégia específica destacada no comando.","C":"A relação social é ampla; o ponto decisivo é a barreira produzida por certos usos.","D":"Consequências aparecem, mas a tese pedida é sustentada pela denúncia dos obstáculos.","E":"A incompreensão dos jargões pode manter pessoas afastadas de decisões que as afetam."},"takeaway":"Um conhecimento especializado pode ser necessário; o problema discutido é seu uso como exclusão.","key":"linguagens:L337","area":"linguagens","year":2023,"number":20,"answer":"E","subject":"Gramática a serviço do sentido","topic":"Classes de palavras, referenciação e efeitos de sentido","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[11],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Traduzir variedades para melhorar o cuidado","steps":["O dicionário aproxima termos regionais e linguagem médica.","O objetivo é evitar que diferenças de vocabulário prejudiquem a consulta.","D identifica melhora na compreensão dos sintomas, não descoberta de doenças novas."],"alternatives":{"A":"Os usos locais são registrados como variedades legítimas, não erros a corrigir.","B":"A dificuldade motiva o projeto, mas a ação é criar uma ponte de compreensão.","C":"Mudar o nome usado para um sintoma não significa descobrir um sintoma novo.","D":"Entender o vocabulário do paciente favorece a comunicação e o diagnóstico.","E":"O levantamento é de termos, não uma lista inédita de doenças locais."},"takeaway":"Adequação comunicativa pode exigir que o profissional compreenda a variedade do interlocutor.","key":"linguagens:L223","area":"linguagens","year":2023,"number":21,"answer":"D","subject":"Variação linguística","topic":"Oralidade, registros e adequação comunicativa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[11],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A cantiga transmite ancestralidade","steps":["A canção passa dos mais velhos aos mais novos e do pai ao filho.","Mesmo sem compreender cada palavra, Luandi reproduz canto e ritmo de retorno.","C destaca preservação da ancestralidade pela tradição oral, sem afirmar extinção da língua."],"alternatives":{"A":"O texto diz que alguns velhos ainda falavam a língua, não que estava extinta.","B":"O patrimônio ultrapassa a rotina dos jovens e reúne várias gerações.","C":"Aprendizado familiar e repetição oral mantêm uma referência ancestral africana.","D":"Luandi não entende as palavras; a alternativa contraria informação expressa.","E":"A cantiga é descrita como alegre, não como manifestação predominante de tristeza."},"takeaway":"Patrimônio linguístico envolve memória e uso social, mesmo quando a compreensão lexical é parcial.","key":"linguagens:L266","area":"linguagens","year":2023,"number":22,"answer":"C","subject":"Variação linguística","topic":"História da língua e diversidade cultural","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[12],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A tecnologia muda; o estereótipo permanece","steps":["O desenho imagina carros voadores, mas mantém piadas machistas sobre mulheres dirigindo.","O segundo texto explica os papéis de gênero como formações imaginárias.","C relaciona a persistência do estereótipo às construções cristalizadas socialmente."],"alternatives":{"A":"Não há uma proibição explícita da fala feminina no episódio analisado.","B":"A mulher está presente, mas representada por um estereótipo, não simplesmente ausente.","C":"A suposta incapacidade é construção social reproduzida pelo desenho, não fato natural.","D":"O segundo texto contesta precisamente a ideia de limitações inerentes aos sexos.","E":"O problema não é não conseguir atribuir papéis, mas repeti-los rigidamente."},"takeaway":"Progresso técnico não implica automaticamente transformação das relações sociais.","key":"linguagens:L093","area":"linguagens","year":2023,"number":23,"answer":"C","subject":"Interpretação de texto e gêneros textuais","topic":"Argumentação e pontos de vista","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[12],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O imperativo revela a finalidade da campanha","steps":["Máscaras e isolamento situam o anúncio na pandemia.","O apelo não se cale, denuncie convoca mulheres a comunicar a violência.","E expressa a finalidade global; telefone, instituição e alerta são meios para essa ação."],"alternatives":{"A":"O telefone é um recurso de acesso, não o objetivo comunicativo completo.","B":"A instituição é identificada, mas o foco é mobilizar a denúncia.","C":"Não se trata principalmente de autopromoção do trabalho institucional.","D":"O alerta contextualiza o apelo; não atribui diretamente ao vírus a prática da violência.","E":"O anúncio conclama mulheres a denunciar crimes durante o isolamento."},"takeaway":"Localize os verbos de ação numa campanha e diferencie finalidade de informação de apoio.","key":"linguagens:L050","area":"linguagens","year":2023,"number":24,"answer":"E","subject":"Interpretação de texto e gêneros textuais","topic":"Gêneros textuais e finalidades comunicativas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[12],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A fala é comparada a um arado","steps":["A narradora escolhe uma palavra ligada ao trabalho do pai.","A dificuldade de pronunciá-la é descrita como arado deformado que dilacera a terra.","B reconhece a metáfora que aproxima linguagem e instrumento de lavoura."],"alternatives":{"A":"O olhar central é o da narradora sobre sua fala, não o do pai sobre o plantio.","B":"O ato de enunciar se figura como lavrar, com o arado torto representando a fala lesionada.","C":"Ela está sozinha, mas não apresenta medo da solidão como núcleo da tentativa.","D":"A terra destruída integra a metáfora da fala, não apenas uma frustração agrícola.","E":"Há memória e tentativa de mudança, não estagnação temporal por ausência de linguagem."},"takeaway":"Acompanhe quando uma imagem deixa de descrever um objeto e passa a representar uma experiência.","key":"linguagens:L369","area":"linguagens","year":2023,"number":25,"answer":"B","subject":"Literatura","topic":"Literatura contemporânea (pós-1960)","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A distância histórica atenua a percepção do horror","steps":["Bilac imagina crianças futuras conhecendo objetos e relatos da escravidão.","Contrasta essa experiência mediada com a indignação de quem viveu o horror.","C aponta o futuro apagamento ou enfraquecimento das marcas na percepção social, sem afirmar desaparecimento de todo legado escravista."],"alternatives":{"A":"A linguagem é fortemente valorativa e comovida, não impessoal.","B":"A comparação principal é entre conhecer depois e testemunhar, não duas infâncias específicas.","C":"O distanciamento do vivido pode enfraquecer a percepção social da violência e de suas marcas.","D":"Não se acusa diretamente os museus de falsificar ou suavizar seus relatos.","E":"O foco recai no futuro e na experiência histórica, não na indiferença dos contemporâneos aos libertos."},"takeaway":"Uma previsão sobre memória social não é prova de que as desigualdades históricas deixaram de existir.","key":"linguagens:L476","area":"linguagens","year":2023,"number":26,"answer":"C","subject":"Literatura","topic":"Outras escolas e tradições literárias","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Todos amplia o alcance da afirmação","steps":["A narradora sustenta que vínculos muito diferentes encontram um fim.","A repetição de todos e suas flexões acumula casos sob a mesma generalização.","A explica a progressão enumerativa que constrói um enredo comum às relações."],"alternatives":{"A":"A repetição totalizante inclui amores, desamores, promessas e vínculos na mesma conclusão.","B":"O travessão introduz explicação, mas não sustenta toda a enumeração universalizante.","C":"Isso retoma duração, não é o mecanismo central da abrangência dos vínculos.","D":"Mas marca oposição local, sem construir sozinho o conjunto enumerado.","E":"Substantivações aparecem, mas não produzem a generalização pela inclusão de todos os casos."},"takeaway":"Progressão textual pode ampliar uma tese por enumeração, mesmo repetindo uma palavra.","key":"linguagens:L315","area":"linguagens","year":2023,"number":27,"answer":"A","subject":"Gramática a serviço do sentido","topic":"Sintaxe, pontuação e relações de sentido","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O eu lírico não consegue dizer como deseja","steps":["Querer falar e gritar se desencontra com a realização da voz.","O nó e o silêncio expressam a experiência subjetiva de bloqueio.","C identifica dificuldade de comunicação; o poema não determina uma causa externa específica."],"alternatives":{"A":"Não há referência suficiente a desilusão amorosa como tema central.","B":"A censura externa é uma interpretação possível, mas não explicitada no poema.","C":"Primeira pessoa e impasses da voz exprimem subjetivamente a dificuldade de comunicar.","D":"O trecho não identifica pressões externas concretas como causa do bloqueio.","E":"Criação artística não é indicada como o processo específico que causa a dor."},"takeaway":"A função emotiva destaca a vivência do emissor; não invente causas que o texto não determina.","key":"linguagens:L288","area":"linguagens","year":2023,"number":28,"answer":"C","subject":"Funções e figuras de linguagem","topic":"Funções da linguagem","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Solenidade histórica e corpo repugnante","steps":["O narrador atribui dignidade e tradição aos ratos de Ouro Preto.","A evocação heroica culmina nos animais penetrando o crânio exposto de Tiradentes.","E identifica o choque entre pompa e repugnância, mais preciso que a mera mistura de ficção e história."],"alternatives":{"A":"Os casarões situam a cena, mas não constituem o choque principal.","B":"A hipótese ficcional participa do efeito, mas não identifica o contraste valorativo decisivo.","C":"A conexão entre animais e literatura é parcial e não explica a imagem final grotesca.","D":"Não se põe em dúvida a sanidade mental dos inconfidentes.","E":"A dignidade solene atribuída à memória histórica colide com a imagem física dos roedores."},"takeaway":"Pergunte quais valores ou registros entram em choque para produzir o efeito desconcertante.","key":"linguagens:L432","area":"linguagens","year":2023,"number":29,"answer":"E","subject":"Literatura","topic":"Modernismo: romance de 1930 e prosa da segunda geração","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[14],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A proibição infiltra medo no cotidiano","steps":["A Companhia proíbe ações banais e ameaça quem tentar escapar.","Os cacos e o gesto de torcer o pescoço tornam a punição concreta e intimidatória.","A lê esse cotidiano como alegoria do autoritarismo e do medo na década de 1970."],"alternatives":{"A":"Regras arbitrárias e punições cercam atos comuns e espalham intimidação.","B":"O trecho não gira em torno de notícias cuja veracidade seja duvidosa.","C":"O absurdo ficcional não significa que a cena seja apresentada como sonho.","D":"A Companhia funciona como poder coercitivo, não como elogio ao desenvolvimento privado.","E":"As crianças são afetadas, mas o controle descrito alcança o conjunto da população."},"takeaway":"Alegorias políticas tornam visível uma estrutura de poder por situações ficcionais do cotidiano.","key":"linguagens:L370","area":"linguagens","year":2023,"number":30,"answer":"A","subject":"Literatura","topic":"Literatura contemporânea (pós-1960)","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[14],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A separação acontece entre migalhas","steps":["O eu lírico imagina cenários grandiosos para o fim do amor.","No entanto, a cena real é um gesto cotidiano à mesa.","C expressa a diluição da comoção na banalidade, sem negar que exista sofrimento."],"alternatives":{"A":"Não há uma convocação explícita para o interlocutor tomar posição.","B":"O poema trata de uma perda particular, não invalida todo envolvimento amoroso.","C":"A ação banal de recolher migalhas contrasta com os cenários solenes imaginados.","D":"O gesto contido não permite concluir que o casal encontrou paz.","E":"Os cenários são imaginados para a despedida, não condições reais da paixão."},"takeaway":"Observe a virada introduzida por no entanto: ela reorganiza o sentido da enumeração anterior.","key":"linguagens:L371","area":"linguagens","year":2023,"number":31,"answer":"C","subject":"Literatura","topic":"Literatura contemporânea (pós-1960)","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[14],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Um repertório reúne referências diferentes","steps":["A apresentação combina o Bolero de Ravel com Asa branca e uma canção paraibana.","O repertório coloca em relação tradição erudita europeia e músicas brasileiras e regionais.","A identifica essa inter-relação, sem estabelecer superioridade entre os gêneros."],"alternatives":{"A":"O mesmo evento articula obras de origens e tradições estéticas distintas.","B":"A serenidade não é o critério textual que explica a seleção inteira.","C":"Tocar Ravel não implica consagrar o erudito como cultura superior.","D":"O contexto turístico existe, mas a pergunta solicita a característica do repertório.","E":"As peças convivem na apresentação, sem divisão explícita de valor entre estilos."},"takeaway":"Diversidade de repertório pode aproximar tradições sem hierarquizá-las.","key":"linguagens:L596","area":"linguagens","year":2023,"number":32,"answer":"A","subject":"Artes","topic":"Música e patrimônio cultural","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[15],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O regime chama de degenerada a estética que rejeita","steps":["A obra apresenta deformação expressiva e composição distante do academicismo idealizado.","O segundo texto descreve sua perseguição em exposições e confiscos nazistas.","A relaciona a condenação à incompatibilidade com o ideário político, não a defeito intrínseco da arte."],"alternatives":{"A":"A classificação é um juízo autoritário contra uma estética considerada inconveniente.","B":"O trecho não demonstra filiação da obra a um grupo partidário de oposição.","C":"A representação parcial do corpo, isoladamente, não explica a censura ideológica.","D":"O regime a rejeita, em vez de reconhecer nela antecipação de seu ideal artístico.","E":"Debater cultura coletivamente não é o fundamento específico da condenação narrada."},"takeaway":"Aspas em qualificações oficiais podem sinalizar um rótulo persecutório, não uma avaliação artística neutra.","key":"linguagens:L621","area":"linguagens","year":2023,"number":33,"answer":"A","subject":"Artes","topic":"História da arte e outras manifestações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[15],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A dança recria, não copia um culto","steps":["O texto e a imagem retomam gestos, atmosfera e referências afro-brasileiras.","O próprio fragmento adverte que não se trata de representação mimética do culto.","C identifica reelaboração estética para o palco, sem dizer que as práticas religiosas estejam extintas."],"alternatives":{"A":"A descrição não se organiza como ataque aos movimentos do balé clássico.","B":"As religiões referidas não são apresentadas como rituais desaparecidos.","C":"A linguagem cênica transforma referências populares em elaboração coreográfica.","D":"Não há sinais suficientes de ridicularização ou ironia dirigida ao culto.","E":"O contraste entre tradição e brevidade da vida não é o tema do espetáculo descrito."},"takeaway":"Reelaboração artística se distingue tanto de cópia literal quanto de caricatura de uma prática cultural.","key":"linguagens:L587","area":"linguagens","year":2023,"number":34,"answer":"C","subject":"Artes","topic":"Dança e expressão corporal","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[15],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Indicadores convergem para a expansão","steps":["O texto reúne crescimento de praticantes, público e interesse institucional.","Esses dados compõem um cenário de reconhecimento e ampliação do esporte eletrônico.","A sintetiza a condição favorável à expansão, sem provar que todo jogo tenha se tornado modalidade olímpica."],"alternatives":{"A":"Audiência, participação e reconhecimento constituem condições favoráveis ao crescimento.","B":"Jogadores contribuem, mas a promoção individual não resume todos os indicadores.","C":"Não se descreve principalmente uma campanha de marketing específica.","D":"Fabricantes podem ganhar com a expansão, mas não são o foco do diagnóstico.","E":"O público citado não se restringe à televisão ou a sua transformação."},"takeaway":"Quando vários indicadores apontam na mesma direção, procure a conclusão que os reúne.","key":"linguagens:L698","area":"linguagens","year":2023,"number":35,"answer":"A","subject":"Educação Física","topic":"Cultura corporal, jogos e lazer","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[16],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Da memória dramática a uma prática coletiva viva","steps":["A narrativa de origem vincula o Marabaixo ao sofrimento da escravidão.","A manifestação passa a integrar danças, cantorias, encontros e festas religiosas.","A abrange essa ressignificação cultural, não apenas a lembrança fúnebre original."],"alternatives":{"A":"O sofrimento histórico é reelaborado em novas práticas e vínculos culturais.","B":"O texto não define a dança como cópia dos movimentos físicos do mar.","C":"O lamento é parte da origem, mas não esgota a função cultural posterior.","D":"Há preservação e recriação da memória, não apagamento do trauma.","E":"Não se descreve simplesmente uma cerimônia de passagem fúnebre com festa."},"takeaway":"Patrimônio vivo transforma memórias em práticas presentes, em vez de apenas conservar uma forma imóvel.","key":"linguagens:L588","area":"linguagens","year":2023,"number":36,"answer":"A","subject":"Artes","topic":"Dança e expressão corporal","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[16],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A plataforma amplia a circulação da obra","steps":["O artista descreve as redes como forma de ampliar universos.","A circulação de colagens em capas no Brasil e no exterior exemplifica o alcance.","C identifica a vitrine internacional e a visibilidade buscadas, não mudança técnica obrigatória na colagem."],"alternatives":{"A":"A rede amplia divulgação, sem resolver especificamente um obstáculo material da técnica.","B":"Capas são um destino das obras, não a estética que ele procura imitar.","C":"As plataformas dão alcance e visibilidade a produções antes limitadas pelo contexto local.","D":"O texto valoriza diferença, mas não define oposição geral às artes tradicionais.","E":"Publicar na rede não torna a técnica da colagem necessariamente tecnológica."},"takeaway":"Meio de circulação e técnica de criação são dimensões diferentes da produção artística.","key":"linguagens:L622","area":"linguagens","year":2023,"number":37,"answer":"C","subject":"Artes","topic":"História da arte e outras manifestações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[16],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O rap articula linguagens e causas indígenas","steps":["Os músicos conhecem o rap pelo rádio e combinam suas formas com ritmos indígenas.","As letras defendem causas como a demarcação de terras.","A identifica fusão de manifestações contemporâneas e cultura indígena, sem supor perda de identidade."],"alternatives":{"A":"A apropriação do rap se combina a ritmos, experiências e reivindicações indígenas.","B":"O texto mostra aproximação de linguagens, não oposição temática obrigatória.","C":"O rádio é via de acesso ao rap, não exemplo de rejeição narrado.","D":"As letras se vinculam diretamente a questões da realidade indígena.","E":"A poesia participa da criação, mas o foco não é um programa de estudo literário."},"takeaway":"Culturas indígenas são dinâmicas e podem recriar linguagens urbanas sem deixar de ser indígenas.","key":"linguagens:L597","area":"linguagens","year":2023,"number":38,"answer":"A","subject":"Artes","topic":"Música e patrimônio cultural","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[16],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Uma mobilização pública produz mudança lexical","steps":["Um cidadão cria uma petição para alterar a definição de casamento.","A adesão e a circulação públicas levam o dicionário a reformular o verbete.","C identifica o agente impulsionador; a mudança de palavras é o resultado, não sua causa."],"alternatives":{"A":"A inclusão de uma nova formulação é efeito da mobilização, não o seu motor.","B":"A importância do casamento é contexto, mas não explica a mudança naquele momento.","C":"O uso público da petição organiza pressão cidadã e gera a alteração noticiada.","D":"A rapidez da difusão do verbete não é descrita como causa do pedido.","E":"Divulgar plataformas genericamente não equivale à mobilização concreta relatada."},"takeaway":"Separe acontecimento impulsionador, instrumento de mobilização e resultado produzido.","key":"linguagens:L729","area":"linguagens","year":2023,"number":39,"answer":"C","subject":"Tecnologias da Informação e Comunicação","topic":"Cultura digital, redes e gêneros digitais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[17],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A inclusão é condicionada por um padrão biológico","steps":["O relato destaca a participação histórica de uma atleta trans.","A regra citada exige um limite hormonal durante certo período para a elegibilidade.","B identifica essa condição biológica padronizada. Trata-se da regra descrita no texto de 2021, não de afirmar um regulamento universal atual."],"alternatives":{"A":"O limite de acesso descrito é hormonal, não a conquista de medalhas.","B":"Um padrão mensurável de testosterona condiciona a participação no relato.","C":"O texto trata da inclusão na categoria feminina, não exige criar uma terceira categoria.","D":"O afastamento faz parte da trajetória pessoal, não é a regra central citada.","E":"O texto menciona terapia hormonal e não afirma impossibilidade absoluta de seu uso."},"takeaway":"Em textos sobre esporte e inclusão, diferencie trajetória pessoal, regra histórica e debate de direitos.","key":"linguagens:L699","area":"linguagens","year":2023,"number":40,"answer":"B","subject":"Educação Física","topic":"Cultura corporal, jogos e lazer","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[17],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O rendimento não elimina necessidades emocionais","steps":["A notícia reúne conquistas, denúncia de abuso e efeitos psicológicos.","Biles questiona tanto o agressor quanto o sistema que deixou a violência persistir.","B aponta a dimensão emocional dos atletas, sem reduzir o caso a baixo desempenho."],"alternatives":{"A":"As medalhas contextualizam a atleta, mas não esgotam o problema relatado.","B":"Abuso e sofrimento psicológico exigem reflexão sobre saúde e proteção emocional.","C":"Comitês são responsabilizados, mas a questão pede a dimensão humana central.","D":"A investigação é contexto do relato, não o foco da relação entre esporte e atleta.","E":"Federações participam do caso, mas não substituem a reflexão sobre a saúde emocional."},"takeaway":"Excelência atlética e sofrimento podem coexistir; a proteção do atleta não se resume ao rendimento.","key":"linguagens:L674","area":"linguagens","year":2023,"number":41,"answer":"B","subject":"Educação Física","topic":"Corpo, saúde e qualidade de vida","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[17],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O acesso ao lazer acompanha desigualdades sociais","steps":["O texto contrapõe práticas prazerosas de lazer e deslocamentos físicos por necessidade.","As oportunidades diversificadas se concentram nas populações mais abastadas.","E reconhece a desigualdade de classes como eixo central, articulado a idade, gênero e raça."],"alternatives":{"A":"Gênero é um marcador relevante, mas não resume o contraste socioeconômico central.","B":"Há referência a programas públicos, portanto inexistência é uma generalização indevida.","C":"Idade influencia a prática, mas não explica sozinha o acesso desigual ao lazer.","D":"Raça integra o quadro de desigualdades, sem substituir o eixo de classe pedido.","E":"Renda e condições sociais distribuem de modo desigual tempo, locais e opções de lazer."},"takeaway":"Atividade física por necessidade de deslocamento não equivale a acesso livre e diversificado ao lazer.","key":"linguagens:L675","area":"linguagens","year":2023,"number":42,"answer":"E","subject":"Educação Física","topic":"Corpo, saúde e qualidade de vida","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[17],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Metáforas fazem a vida continuar na obra","steps":["O discurso substitui morte como aniquilação por transformação e presença.","Aliança, noivado, florescência e frutificação articulam vida pessoal e criação literária.","A identifica as metáforas da homenagem, mais específicas que uma simples nostalgia."],"alternatives":{"A":"Imagens de união e cultivo reinterpretam a trajetória e a permanência do escritor.","B":"Há elaboração sonora, mas ela não é o recurso central solicitado.","C":"Predominam construções longas e elaboradas, não relato curto e direto.","D":"As oposições são construídas pelo orador, não apresentadas como ideias da obra de Machado.","E":"A valorização da permanência não se reduz a vocabulário de saudade."},"takeaway":"Metáforas transferem sentidos de um domínio para outro e podem organizar um discurso inteiro.","key":"linguagens:L309","area":"linguagens","year":2023,"number":43,"answer":"A","subject":"Funções e figuras de linguagem","topic":"Figuras de linguagem e efeitos expressivos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[18],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Uma lista de benefícios sustenta a campanha","steps":["A pergunta sobre a importância de amamentar é respondida por tópicos no cartaz.","Eles apontam proteção e aspectos do desenvolvimento do bebê.","A descreve a finalidade de divulgar benefícios; a imagem não apresenta protocolo de tratamento individual."],"alternatives":{"A":"Os tópicos enumeram benefícios atribuídos à amamentação para o bebê.","B":"Não há prescrição de tratamento para uma infecção já instalada.","C":"A foto não transforma a campanha numa discussão sobre direito de amamentar em público.","D":"O cartaz não ensina uma sequência de exercícios ou de posicionamento.","E":"A referência a anticorpos diz respeito à proteção recebida pelo bebê, não ao aumento nas mães."},"takeaway":"Analise o que o cartaz comunica sem convertê-lo em recomendação clínica individual.","key":"linguagens:L094","area":"linguagens","year":2023,"number":44,"answer":"A","subject":"Interpretação de texto e gêneros textuais","topic":"Argumentação e pontos de vista","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[18],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Uma carta pública chama atenção para um problema","steps":["A carta se dirige a cidadãos e apresenta deficiências na rede de atenção ao idoso.","A entidade pede reflexão de governantes, mas usa a divulgação pública para mobilizar o debate.","E abrange o objetivo de chamar a população a olhar a qualidade dos serviços de saúde."],"alternatives":{"A":"O foco não é orientar cuidados individuais do idoso com sua própria saúde.","B":"Governantes são chamados à responsabilidade, mas o destinatário público é mais amplo.","C":"A entidade assina a carta para se posicionar, não principalmente para anunciar seu trabalho.","D":"O texto denuncia falhas de atendimento, não demonstra retrocesso de uma legislação específica.","E":"A carta torna públicas as insuficiências da atenção à saúde da população idosa."},"takeaway":"Numa carta aberta, diferencie quem é cobrado de agir e o público amplo mobilizado pela publicação.","key":"linguagens:L051","area":"linguagens","year":2023,"number":45,"answer":"E","subject":"Interpretação de texto e gêneros textuais","topic":"Gêneros textuais e finalidades comunicativas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"linguagens/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2023.pdf","sourceExamPages":[18],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}}];
